[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Aid Alliance — Together We Respond</title>
<meta name="description" content="A humanitarian nonprofit organization dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --red:#C41E3A;
  --red-dark:#A3182F;
  --red-light:#E8D0D5;
  --navy:#1B3A5C;
  --navy-dark:#122841;
  --navy-light:#2A5580;
  --white:#FFFFFF;
  --gray-50:#F9FAFB;
  --gray-100:#F3F4F6;
  --gray-200:#E5E7EB;
  --gray-300:#D1D5DB;
  --gray-400:#9CA3AF;
  --gray-500:#6B7280;
  --gray-600:#4B5563;
  --gray-700:#374151;
  --gray-800:#1F2937;
  --gray-900:#111827;
  --font-heading:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;
  --font-body:'Segoe UI',Roboto,'Helvetica Neue',Arial,sans-serif;
  --shadow-sm:0 1px 2px rgba(0,0,0,.05);
  --shadow-md:0 4px 6px -1px rgba(0,0,0,.1),0 2px 4px -2px rgba(0,0,0,.1);
  --shadow-lg:0 10px 15px -3px rgba(0,0,0,.1),0 4px 6px -4px rgba(0,0,0,.1);
  --shadow-xl:0 20px 25px -5px rgba(0,0,0,.1),0 8px 10px -6px rgba(0,0,0,.1);
  --radius:8px;
  --transition:0.3s ease;
}
html{scroll-behavior:smooth;font-size:16px}
body{font-family:var(--font-body);color:var(--gray-800);line-height:1.6;background:var(--white);overflow-x:hidden}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{cursor:pointer;font-family:inherit;border:none;background:none}
ul{list-style:none}
.container{width:100%;max-width:1200px;margin:0 auto;padding:0 24px}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* ========== HEADER ========== */
.header{position:fixed;top:0;left:0;right:0;z-index:1000;background:var(--white);border-bottom:1px solid var(--gray-200);transition:box-shadow var(--transition)}
.header.scrolled{box-shadow:var(--shadow-md)}
.header-utility{background:var(--navy);color:var(--white);font-size:0.8rem;padding:6px 0}
.header-utility .container{display:flex;justify-content:flex-end;align-items:center;gap:16px}
.header-utility a{color:var(--white);opacity:0.85;transition:opacity var(--transition)}
.header-utility a:hover{opacity:1}
.header-main .container{display:flex;align-items:center;justify-content:space-between;padding-top:12px;padding-bottom:12px}
.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:1.25rem;color:var(--navy)}
.logo-icon{width:40px;height:40px;background:var(--red);border-radius:50%;display:flex;align-items:center;justify-content:center}
.logo-icon svg{width:22px;height:22px;fill:var(--white)}
.nav-desktop{display:flex;align-items:center;gap:6px}
.nav-desktop a{padding:8px 14px;font-size:0.925rem;font-weight:500;color:var(--gray-700);border-radius:var(--radius);transition:background var(--transition),color var(--transition)}
.nav-desktop a:hover{background:var(--gray-100);color:var(--navy)}
.btn-donate-nav{background:var(--red)!important;color:var(--white)!important;font-weight:600!important;padding:10px 22px!important;border-radius:var(--radius)!important;transition:background var(--transition)!important}
.btn-donate-nav:hover{background:var(--red-dark)!important}
.hamburger{display:none;flex-direction:column;gap:5px;padding:8px;cursor:pointer;z-index:1001}
.hamburger span{display:block;width:24px;height:2.5px;background:var(--gray-700);border-radius:2px;transition:transform var(--transition),opacity var(--transition)}
.hamburger.active span:nth-child(1){transform:translateY(7.5px) rotate(45deg)}
.hamburger.active span:nth-child(2){opacity:0}
.hamburger.active span:nth-child(3){transform:translateY(-7.5px) rotate(-45deg)}
.mobile-nav{position:fixed;top:0;right:-100%;width:min(320px,85vw);height:100vh;background:var(--white);z-index:999;padding:80px 24px 24px;box-shadow:var(--shadow-xl);transition:right var(--transition);overflow-y:auto}
.mobile-nav.open{right:0}
.mobile-nav a{display:block;padding:14px 0;font-size:1.05rem;font-weight:500;color:var(--gray-700);border-bottom:1px solid var(--gray-100)}
.mobile-nav a:last-child{border-bottom:none}
.mobile-nav .btn-donate-mobile{display:block;text-align:center;margin-top:20px;background:var(--red);color:var(--white);padding:14px;border-radius:var(--radius);font-weight:600;font-size:1.05rem}
.mobile-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.4);z-index:998;opacity:0;visibility:hidden;transition:opacity var(--transition),visibility var(--transition)}
.mobile-overlay.open{opacity:1;visibility:visible}

/* ========== HERO ========== */
.hero{position:relative;min-height:600px;display:flex;align-items:center;background:linear-gradient(135deg,var(--navy) 0%,var(--navy-dark) 100%);color:var(--white);padding:140px 0 80px;overflow:hidden}
.hero::before{content:'';position:absolute;inset:0;background:url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 600"><circle cx="200" cy="300" r="400" fill="rgba(196,30,58,0.08)"/><circle cx="1200" cy="100" r="300" fill="rgba(196,30,58,0.05)"/><circle cx="800" cy="500" r="250" fill="rgba(27,58,92,0.1)"/></svg>') center/cover no-repeat}
.hero .container{position:relative;z-index:1;max-width:800px}
.hero h1{font-family:var(--font-heading);font-size:clamp(2.2rem,5vw,3.5rem);font-weight:800;line-height:1.15;margin-bottom:20px;letter-spacing:-0.02em}
.hero p{font-size:clamp(1.05rem,2vw,1.25rem);line-height:1.7;opacity:0.9;margin-bottom:36px;max-width:640px}
.hero-ctas{display:flex;flex-wrap:wrap;gap:16px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 32px;font-size:1rem;font-weight:600;border-radius:var(--radius);transition:all var(--transition);cursor:pointer;border:2px solid transparent}
.btn-primary{background:var(--red);color:var(--white);border-color:var(--red)}
.btn-primary:hover{background:var(--red-dark);border-color:var(--red-dark);transform:translateY(-1px);box-shadow:0 4px 12px rgba(196,30,58,0.4)}
.btn-secondary{background:transparent;color:var(--white);border-color:rgba(255,255,255,0.5)}
.btn-secondary:hover{background:rgba(255,255,255,0.1);border-color:var(--white)}

/* ========== MISSION ========== */
.mission{padding:80px 0;background:var(--white)}
.mission .container{max-width:860px;text-align:center}
.section-label{display:inline-block;font-size:0.8rem;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;color:var(--red);margin-bottom:12px}
.mission h2{font-family:var(--font-heading);font-size:clamp(1.6rem,3.5vw,2.2rem);font-weight:700;color:var(--navy);margin-bottom:24px;line-height:1.3}
.mission p{font-size:1.05rem;color:var(--gray-600);line-height:1.8}

/* ========== IMPACT STATS ========== */
.impact{padding:80px 0;background:var(--navy);color:var(--white);position:relative;overflow:hidden}
.impact::before{content:'';position:absolute;top:-50%;left:-10%;width:50%;height:200%;background:radial-gradient(circle,rgba(196,30,58,0.1) 0%,transparent 70%);pointer-events:none}
.impact .container{position:relative;z-index:1}
.impact-heading{text-align:center;margin-bottom:48px}
.impact-heading .section-label{color:rgba(255,255,255,0.6)}
.impact-heading h2{font-family:var(--font-heading);font-size:clamp(1.6rem,3.5vw,2.2rem);font-weight:700;color:var(--white)}
.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:32px}
.stat-card{text-align:center;padding:32px 16px}
.stat-number{font-family:var(--font-heading);font-size:clamp(2rem,4vw,3rem);font-weight:800;color:var(--white);line-height:1.1;margin-bottom:8px}
.stat-number .counter{display:inline}
.stat-prefix{font-size:0.7em}
.stat-suffix{font-size:0.5em;font-weight:600}
.stat-label{font-size:0.95rem;color:rgba(255,255,255,0.75);font-weight:500}
.stat-divider{width:40px;height:3px;background:var(--red);margin:16px auto 0;border-radius:2px}

/* ========== PROGRAMS ========== */
.programs{padding:80px 0;background:var(--gray-50)}
.programs-header{text-align:center;margin-bottom:48px}
.programs-header h2{font-family:var(--font-heading);font-size:clamp(1.6rem,3.5vw,2.2rem);font-weight:700;color:var(--navy)}
.accordion{max-width:800px;margin:0 auto;display:flex;flex-direction:column;gap:8px}
.accordion-item{background:var(--white);border-radius:var(--radius);box-shadow:var(--shadow-sm);overflow:hidden;border:1px solid var(--gray-200);transition:box-shadow var(--transition)}
.accordion-item:hover{box-shadow:var(--shadow-md)}
.accordion-trigger{width:100%;display:flex;align-items:center;justify-content:space-between;padding:20px 24px;font-size:1.05rem;font-weight:600;color:var(--navy);background:transparent;text-align:left;cursor:pointer;transition:background var(--transition)}
.accordion-trigger:hover{background:var(--gray-50)}
.accordion-trigger .icon-left{display:flex;align-items:center;gap:12px}
.accordion-trigger .program-icon{width:36px;height:36px;background:var(--red-light);border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--red);font-size:1.1rem}
.accordion-trigger .chevron{width:20px;height:20px;transition:transform var(--transition);flex-shrink:0;color:var(--gray-400)}
.accordion-item.open .accordion-trigger .chevron{transform:rotate(180deg)}
.accordion-content{max-height:0;overflow:hidden;transition:max-height 0.4s ease}
.accordion-content-inner{padding:0 24px 20px 72px;color:var(--gray-600);line-height:1.7;font-size:0.95rem}

/* ========== GET INVOLVED ========== */
.get-involved{padding:80px 0;background:var(--white)}
.get-involved-header{text-align:center;margin-bottom:48px}
.get-involved-header h2{font-family:var(--font-heading);font-size:clamp(1.6rem,3.5vw,2.2rem);font-weight:700;color:var(--navy)}
.involve-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.involve-card{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);padding:36px 28px;text-align:center;transition:transform var(--transition),box-shadow var(--transition)}
.involve-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.involve-icon{width:64px;height:64px;margin:0 auto 20px;background:var(--red-light);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:1.6rem}
.involve-card h3{font-family:var(--font-heading);font-size:1.15rem;font-weight:700;color:var(--navy);margin-bottom:12px}
.involve-card p{font-size:0.92rem;color:var(--gray-600);line-height:1.6;margin-bottom:20px}
.btn-outline{display:inline-flex;align-items:center;gap:6px;padding:10px 24px;font-size:0.9rem;font-weight:600;color:var(--red);border:2px solid var(--red);border-radius:var(--radius);transition:all var(--transition)}
.btn-outline:hover{background:var(--red);color:var(--white)}

/* ========== NEWS ========== */
.news{padding:80px 0;background:var(--gray-50)}
.news-header{text-align:center;margin-bottom:48px}
.news-header h2{font-family:var(--font-heading);font-size:clamp(1.6rem,3.5vw,2.2rem);font-weight:700;color:var(--navy)}
.carousel-wrapper{position:relative;overflow:hidden}
.carousel-track{display:flex;transition:transform 0.5s ease;gap:24px}
.news-card{min-width:calc(33.333% - 16px);background:var(--white);border-radius:var(--radius);box-shadow:var(--shadow-sm);border:1px solid var(--gray-200);overflow:hidden;flex-shrink:0;transition:box-shadow var(--transition)}
.news-card:hover{box-shadow:var(--shadow-md)}
.news-card-img{height:180px;background:var(--gray-200);display:flex;align-items:center;justify-content:center;color:var(--gray-400);font-size:0.85rem;position:relative;overflow:hidden}
.news-card-img::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,var(--navy) 0%,rgba(27,58,92,0.6) 100%);opacity:0.15}
.news-card-img span{position:relative;z-index:1;text-align:center;padding:0 16px}
.news-card-body{padding:24px}
.news-card-tag{display:inline-block;font-size:0.75rem;font-weight:700;text-transform:uppercase;letter-spacing:0.05em;color:var(--red);margin-bottom:10px}
.news-card h3{font-family:var(--font-heading);font-size:1.05rem;font-weight:700;color:var(--navy);margin-bottom:10px;line-height:1.4}
.news-card p{font-size:0.88rem;color:var(--gray-600);line-height:1.6}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;background:var(--white);box-shadow:var(--shadow-lg);display:flex;align-items:center;justify-content:center;z-index:10;border:1px solid var(--gray-200);transition:all var(--transition);color:var(--navy)}
.carousel-btn:hover{background:var(--navy);color:var(--white)}
.carousel-btn.prev{left:8px}
.carousel-btn.next{right:8px}
.carousel-btn:disabled{opacity:0.3;cursor:not-allowed}
.carousel-btn:disabled:hover{background:var(--white);color:var(--navy)}
.carousel-dots{display:flex;justify-content:center;gap:8px;margin-top:28px}
.carousel-dot{width:10px;height:10px;border-radius:50%;background:var(--gray-300);border:none;cursor:pointer;transition:all var(--transition)}
.carousel-dot.active{background:var(--red);width:28px;border-radius:5px}

/* ========== DONATE CTA ========== */
.donate-cta{padding:80px 0;background:linear-gradient(135deg,var(--red) 0%,var(--red-dark) 100%);color:var(--white);text-align:center}
.donate-cta h2{font-family:var(--font-heading);font-size:clamp(1.8rem,4vw,2.5rem);font-weight:800;margin-bottom:16px}
.donate-cta>p,.donate-cta .container>p{font-size:1.1rem;opacity:0.92;max-width:600px;margin:0 auto 12px;line-height:1.7}
.donate-efficiency{font-size:1.15rem;font-weight:700;margin-bottom:32px;opacity:0.95}
.btn-donate-cta{background:var(--white);color:var(--red);font-size:1.1rem;padding:16px 40px;font-weight:700;border-radius:var(--radius);transition:all var(--transition);border:2px solid var(--white);display:inline-flex;align-items:center;gap:8px}
.btn-donate-cta:hover{background:transparent;color:var(--white);transform:translateY(-2px);box-shadow:0 6px 20px rgba(0,0,0,0.2)}

/* ========== FOOTER ========== */
.footer{background:var(--gray-900);color:var(--gray-400);padding:60px 0 0}
.footer-grid{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:40px;padding-bottom:48px;border-bottom:1px solid rgba(255,255,255,0.1)}
.footer-brand h3{font-family:var(--font-heading);font-size:1.3rem;font-weight:700;color:var(--white);margin-bottom:12px}
.footer-brand p{font-size:0.88rem;line-height:1.6;margin-bottom:20px}
.footer-social{display:flex;gap:12px}
.footer-social a{width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,0.1);display:flex;align-items:center;justify-content:center;transition:background var(--transition);font-size:0.8rem;color:var(--gray-400)}
.footer-social a:hover{background:var(--red);color:var(--white)}
.footer-col h4{font-size:0.85rem;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:var(--white);margin-bottom:16px}
.footer-col a{display:block;font-size:0.88rem;padding:4px 0;transition:color var(--transition)}
.footer-col a:hover{color:var(--white)}
.footer-bottom{padding:24px 0;text-align:center;font-size:0.8rem}

/* ========== DONATION MODAL ========== */
.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:2000;display:flex;align-items:center;justify-content:center;opacity:0;visibility:hidden;transition:opacity var(--transition),visibility var(--transition);padding:20px;backdrop-filter:blur(4px)}
.modal-overlay.open{opacity:1;visibility:visible}
.modal{background:var(--white);border-radius:12px;width:100%;max-width:520px;max-height:90vh;overflow-y:auto;transform:scale(0.95);transition:transform var(--transition);box-shadow:var(--shadow-xl)}
.modal-overlay.open .modal{transform:scale(1)}
.modal-header{display:flex;align-items:center;justify-content:space-between;padding:24px 28px 0}
.modal-header h2{font-family:var(--font-heading);font-size:1.4rem;font-weight:700;color:var(--navy)}
.modal-close{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--gray-500);font-size:1.3rem;transition:background var(--transition)}
.modal-close:hover{background:var(--gray-100)}
.modal-body{padding:24px 28px 28px}
.modal-subtitle{font-size:0.95rem;color:var(--gray-600);margin-bottom:24px;line-height:1.5}
.amount-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:20px}
.amount-option{position:relative}
.amount-option input{position:absolute;opacity:0;pointer-events:none}
.amount-option label{display:block;padding:16px;border:2px solid var(--gray-200);border-radius:var(--radius);text-align:center;cursor:pointer;transition:all var(--transition)}
.amount-option label:hover{border-color:var(--red)}
.amount-option input:checked+label{border-color:var(--red);background:rgba(196,30,58,0.05);color:var(--red)}
.amount-value{font-size:1.2rem;font-weight:700;color:var(--navy);display:block}
.amount-option input:checked+label .amount-value{color:var(--red)}
.amount-impact{font-size:0.78rem;color:var(--gray-500);margin-top:4px;display:block;line-height:1.3}
.custom-amount{margin-bottom:24px}
.custom-amount label{display:block;font-size:0.88rem;font-weight:600;color:var(--gray-700);margin-bottom:8px}
.custom-amount-input{display:flex;align-items:center;border:2px solid var(--gray-200);border-radius:var(--radius);overflow:hidden;transition:border-color var(--transition)}
.custom-amount-input:focus-within{border-color:var(--red)}
.custom-amount-input span{padding:12px 14px;background:var(--gray-50);font-weight:600;color:var(--gray-500);border-right:1px solid var(--gray-200)}
.custom-amount-input input{flex:1;border:none;padding:12px;font-size:1rem;outline:none;font-family:inherit}
.btn-submit-donation{width:100%;padding:16px;background:var(--red);color:var(--white);font-size:1.05rem;font-weight:700;border-radius:var(--radius);border:none;cursor:pointer;transition:background var(--transition)}
.btn-submit-donation:hover{background:var(--red-dark)}
.modal-trust{display:flex;align-items:center;justify-content:center;gap:8px;margin-top:16px;font-size:0.8rem;color:var(--gray-500)}
.modal-trust svg{width:14px;height:14px;fill:var(--gray-400)}

/* ========== ANIMATIONS ========== */
@keyframes fadeInUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:translateY(0)}}
.animate-on-scroll{opacity:0;transform:translateY(24px);transition:opacity 0.6s ease,transform 0.6s ease}
.animate-on-scroll.visible{opacity:1;transform:translateY(0)}

/* ========== RESPONSIVE ========== */
@media(max-width:1024px){
  .stats-grid{grid-template-columns:repeat(2,1fr);gap:24px}
  .involve-grid{grid-template-columns:repeat(2,1fr)}
  .news-card{min-width:calc(50% - 12px)}
  .footer-grid{grid-template-columns:repeat(2,1fr);gap:32px}
}
@media(max-width:768px){
  .nav-desktop{display:none}
  .hamburger{display:flex}
  .hero{min-height:auto;padding:120px 0 60px}
  .hero h1{font-size:2rem}
  .stats-grid{grid-template-columns:repeat(2,1fr);gap:16px}
  .stat-card{padding:20px 12px}
  .involve-grid{grid-template-columns:1fr}
  .news-card{min-width:calc(100% - 0px)}
  .carousel-btn{width:36px;height:36px}
  .footer-grid{grid-template-columns:1fr;gap:28px}
  .header-utility{display:none}
  .amount-grid{grid-template-columns:repeat(2,1fr)}
}
@media(max-width:480px){
  .hero-ctas{flex-direction:column}
  .hero-ctas .btn{width:100%;justify-content:center}
  .stats-grid{grid-template-columns:1fr 1fr;gap:12px}
  .stat-number{font-size:1.8rem}
}
</style>
</head>
<body>

<!-- ========== HEADER ========== -->
<header class="header" id="header">
  <div class="header-utility">
    <div class="container">
      <a href="#signin">Sign In</a>
      <a href="#contact">Contact Us</a>
      <a href="#espanol" lang="es">Espa&ntilde;ol</a>
    </div>
  </div>
  <div class="header-main">
    <div class="container">
      <a href="#" class="logo" aria-label="Global Aid Alliance home">
        <div class="logo-icon">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>
        </div>
        <span>Global Aid Alliance</span>
      </a>
      <nav class="nav-desktop" aria-label="Main navigation">
        <a href="#about">About Us</a>
        <a href="#programs">Disaster Relief</a>
