<script>
(function(){
  // Header scroll effect
  var header = document.getElementById('header');
  window.addEventListener('scroll', function(){
    header.classList.toggle('scrolled', window.scrollY > 10);
  });

  // Mobile menu
  var hamburger = document.getElementById('hamburgerBtn');
  var mobileNav = document.getElementById('mobileNav');
  var overlay = document.getElementById('mobileOverlay');

  hamburger.addEventListener('click', function(){
    var isOpen = mobileNav.classList.contains('open');
    if (isOpen) {
      closeMobileMenu();
    } else {
      mobileNav.classList.add('open');
      overlay.classList.add('open');
      hamburger.classList.add('active');
      hamburger.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }
  });

  overlay.addEventListener('click', closeMobileMenu);

  window.closeMobileMenu = function(){
    mobileNav.classList.remove('open');
    overlay.classList.remove('open');
    hamburger.classList.remove('active');
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  };

  // Donation modal
  window.openDonateModal = function(){
    document.getElementById('donateModal').classList.add('open');
    document.body.style.overflow = 'hidden';
  };

  window.closeDonateModal = function(){
    document.getElementById('donateModal').classList.remove('open');
    document.body.style.overflow = '';
  };

  document.getElementById('donateModal').addEventListener('click', function(e){
    if (e.target === this) closeDonateModal();
  });

  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape') {
      closeDonateModal();
      closeMobileMenu();
    }
  });

  window.submitDonation = function(){
    var selected = document.querySelector('input[name=donation]:checked');
    var custom = document.getElementById('customAmount').value;
    var amount = custom ? '$' + custom : (selected ? '$' + selected.value : '$25');
    alert('Thank you for your generous donation of ' + amount + '! In a production environment, this would redirect to a secure payment processor.');
    closeDonateModal();
  };

  // Accordion
  document.querySelectorAll('.accordion-trigger').forEach(function(trigger){
    trigger.addEventListener('click', function(){
      var item = this.parentElement;
      var content = item.querySelector('.accordion-content');
      var isOpen = item.classList.contains('open');

      document.querySelectorAll('.accordion-item').forEach(function(el){
        el.classList.remove('open');
        el.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
        el.querySelector('.accordion-content').style.maxHeight = null;
      });

      if (!isOpen) {
        item.classList.add('open');
        this.setAttribute('aria-expanded', 'true');
        content.style.maxHeight = content.scrollHeight + 'px';
      }
    });
  });

  // News carousel
  var track = document.getElementById('carouselTrack');
  var prevBtn = document.getElementById('carouselPrev');
  var nextBtn = document.getElementById('carouselNext');
  var dotsContainer = document.getElementById('carouselDots');
  var currentSlide = 0;

  function getVisibleCount(){
    var w = window.innerWidth;
    if (w <= 768) return 1;
    if (w <= 1024) return 2;
    return 3;
  }

  function getTotalSlides(){
    return Math.max(1, 4 - getVisibleCount() + 1);
  }

  function renderDots(){
    dotsContainer.innerHTML = '';
    var total = getTotalSlides();
    for (var i = 0; i < total; i++){
      var dot = document.createElement('button');
      dot.className = 'carousel-dot' + (i === currentSlide ? ' active' : '');
      dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
      dot.dataset.index = i;
      dot.addEventListener('click', function(){
        currentSlide = parseInt(this.dataset.index);
        updateCarousel();
      });
      dotsContainer.appendChild(dot);
    }
  }

  function updateCarousel(){
    var visible = getVisibleCount();
    var total = getTotalSlides();
    if (currentSlide >= total) currentSlide = total - 1;
    if (currentSlide < 0) currentSlide = 0;

    var cards = track.querySelectorAll('.news-card');
    var gap = 24;
    var cardWidth = (track.parentElement.offsetWidth - gap * (visible - 1)) / visible;
    cards.forEach(function(card){ card.style.minWidth = cardWidth + 'px'; });

    var offset = currentSlide * (cardWidth + gap);
    track.style.transform = 'translateX(-' + offset + 'px)';

    prevBtn.disabled = currentSlide === 0;
    nextBtn.disabled = currentSlide >= total - 1;

    renderDots();
  }

  prevBtn.addEventListener('click', function(){ currentSlide--; updateCarousel(); });
  nextBtn.addEventListener('click', function(){ currentSlide++; updateCarousel(); });

  window.addEventListener('resize', function(){ updateCarousel(); });
  updateCarousel();

  // Animated counters
  function animateCounters(){
    document.querySelectorAll('.counter').forEach(function(counter){
      if (counter.dataset.animated) return;
      var rect = counter.getBoundingClientRect();
      if (rect.top > window.innerHeight || rect.bottom < 0) return;

      counter.dataset.animated = 'true';
      var target = parseInt(counter.dataset.target);
      var format = counter.dataset.format;
      var duration = 2000;
      var start = 0;
      var startTime = null;

      function easeOut(t){ return 1 - Math.pow(1 - t, 3); }

      function step(timestamp){
        if (!startTime) startTime = timestamp;
        var progress = Math.min((timestamp - startTime) / duration, 1);
        var current = Math.floor(easeOut(progress) * target);
        counter.textContent = format === 'comma' ? current.toLocaleString() : current;
        if (progress < 1) requestAnimationFrame(step);
        else counter.textContent = format === 'comma' ? target.toLocaleString() : target;
      }
      requestAnimationFrame(step);
    });
  }

